  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ========================\n// SUBSCRIPCIÓN\n// ========================\nmodel SubscriptionPlan {\n  id          String   @id @default(uuid())\n  name        PlanType @unique\n  description String?\n  price       Float // Precio mensual\n  features    Json // Lista de beneficios/características del plan\n\n  subscriptions UserSubscription[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel UserSubscription {\n  id     String @id @default(uuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id])\n\n  planId String\n  plan   SubscriptionPlan @relation(fields: [planId], references: [id])\n\n  startDate   DateTime @default(now())\n  renewalDate DateTime\n  active      Boolean  @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ========================\n// USER MANAGEMENT\n// ========================\nmodel User {\n  id       String @id @default(uuid())\n  email    String @unique\n  password String\n\n  profile  UserProfile?\n  tokens   UserToken[]\n  recovery UserRecovery?\n\n  lifeWheel LifeWheel[]\n  contexts  Context[] // ✅ Contextos globales de cada usuario\n\n  subscription UserSubscription?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel UserProfile {\n  id     String @id @default(uuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id])\n\n  firstName String\n  lastName  String\n  address   String\n  phone     String\n  avatarUrl String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel UserToken {\n  id     String @id @default(uuid())\n  userId String @unique // ✅ Un solo token por usuario\n  user   User   @relation(fields: [userId], references: [id])\n\n  accessToken  String\n  refreshToken String?\n  expiresAt    DateTime\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel UserRecovery {\n  id     String @id @default(uuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id])\n\n  recoveryEmail    String?\n  securityQuestion String?\n  securityAnswer   String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ========================\n// LIFEWHEEL\n// ========================\nmodel LifeWheel {\n  id     String @id @default(uuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  lifeAreas   LifeWheelArea[]\n  globalScore Float // Promedio de los scores de las áreas\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ========================\n// ÁREAS DE LA RUEDA DE LA VIDA\n// ========================\nmodel LifeWheelArea {\n  id          String    @id @default(uuid())\n  lifeWheelId String\n  lifeWheel   LifeWheel @relation(fields: [lifeWheelId], references: [id])\n\n  area  LifeArea\n  score Float // Promedio de respuestas Sí/No\n\n  questions Question[]\n  projects  GtdProject[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([lifeWheelId, area])\n}\n\n// ========================\n// PREGUNTAS DE CADA ÁREA\n// ========================\nmodel Question {\n  id              String        @id @default(uuid())\n  lifeWheelAreaId String\n  lifeWheelArea   LifeWheelArea @relation(fields: [lifeWheelAreaId], references: [id])\n\n  text   String\n  answer Boolean // Sí = true, No = false\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ========================\n// PROJECTS\n// ========================\nmodel GtdProject {\n  id              String        @id @default(uuid())\n  lifeWheelAreaId String\n  lifeWheelArea   LifeWheelArea @relation(fields: [lifeWheelAreaId], references: [id])\n\n  title       String\n  description String?\n  status      ProjectStatus @default(ACTIVE)\n\n  detail GtdProjectDetail?\n  budget Budget?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel GtdProjectDetail {\n  id        String     @id @default(uuid())\n  projectId String     @unique\n  project   GtdProject @relation(fields: [projectId], references: [id])\n\n  lifeArea LifeArea\n  status   ProjectDetailStatus @default(PLANNING)\n\n  startDate DateTime\n  endDate   DateTime\n\n  // Metas unificadas (BE–DO–HAVE)\n  goals ProjectGoal[]\n\n  completedActions   Int   @default(0)\n  totalActions       Int   @default(0)\n  progressPercentage Float @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ========================\n// GOALS (Unified)\n// ========================\nmodel ProjectGoal {\n  id       String           @id @default(uuid())\n  detailId String\n  detail   GtdProjectDetail @relation(fields: [detailId], references: [id])\n\n  goalType GoalType // BE, DO, HAVE\n  content  String\n\n  cost  Float? // 💰 costo asociado\n  saved Float? // 💵 ahorro/acumulado\n\n  actions GtdAction[]\n}\n\n// ========================\n// ACTIONS\n// ========================\nmodel GtdAction {\n  id     String      @id @default(uuid())\n  goalId String\n  goal   ProjectGoal @relation(fields: [goalId], references: [id])\n\n  contextId String?\n  context   Context? @relation(fields: [contextId], references: [id])\n\n  title       String\n  description String?\n\n  energy       EnergyLevel\n  timeEstimate Int?\n\n  dueDate     DateTime?\n  completed   Boolean   @default(false)\n  completedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ========================\n// CONTEXT\n// ========================\nmodel Context {\n  id     String @id @default(uuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  actions GtdAction[] // ✅ Relación 1:N con acciones\n\n  name String\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, name]) // ✅ Un contexto único por usuario\n}\n\n// ========================\n// BUDGET (IMO / IDO)\n// ========================\nmodel Budget {\n  id        String     @id @default(uuid())\n  projectId String     @unique\n  project   GtdProject @relation(fields: [projectId], references: [id])\n\n  monthlyIncomeTarget Float? // IMO opcional\n  dailyIncomeTarget   Float? // IDO opcional\n\n  currencyId String\n  currency   Currency @relation(fields: [currencyId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ========================\n// CURRENCY\n// ========================\nmodel Currency {\n  id     String @id @default(uuid())\n  code   String @unique // Ej: \"USD\", \"MXN\"\n  name   String // Ej: \"US Dollar\", \"Peso Mexicano\"\n  symbol String // Ej: \"$\"\n\n  budgets Budget[]\n}\n\n// ========================\n// ENUMS\n// ========================\nenum LifeArea {\n  PERSONAL_DEVELOPMENT\n  PROFESSIONAL_ACTIVITY\n  HEALTH_NUTRITION\n  MONEY_FINANCES\n  SOCIAL_RELATIONSHIPS\n  COUPLE_INTIMACY\n}\n\nenum ProjectDetailStatus {\n  PLANNING\n  ACTIVE\n  COMPLETED\n  ABANDONED\n}\n\nenum ProjectStatus {\n  ACTIVE\n  SOMEDAY\n  COMPLETED\n  CANCELLED\n}\n\nenum EnergyLevel {\n  HIGH\n  MEDIUM\n  LOW\n}\n\nenum GoalType {\n  BE\n  DO\n  HAVE\n}\n\nenum PlanType {\n  BASICO\n  INTERMEDIO\n  AVANZADO\n}\n",
